// ── source: vcx/tests/lint_field_read_test.v ──
// lint_field_read_test.v — #610: CX-L007 flags $count/$empty/$exists over a
// SIMPLE FIELD ACCESSOR (a pure /name child chain — the code.md §6.2
// field-read shape, whose aggregation reports the field's CONTENT arity,
// ruled by-design in #584) and teaches the sanctioned match-counting idioms.
// Warning severity, detect-only. Node-set forms (//, /*, predicates),
// bare bindings, dot-chains, and non-aggregation reads never fire.

fn l7_bin() string {
	return testenv.cx_bin()
}

fn l7_out(src string) string {
	f := os.join_path(os.temp_dir(), 'cx_l007_${os.getpid()}_${src.len}.cx')
	os.write_file(f, src) or { panic('write: ${err}') }
	defer { os.rm(f) or {} }
	r := os.execute('${l7_bin()} lint ${f}')
	return r.output
}

fn l7_count(out string) int {
	mut n := 0
	for line in out.split('\n') {
		if line.contains('CX-L007') {
			n++
		}
	}
	return n
}

fn test_lint_dispatch_agrees_with_fmt_on_program_docs() {
	// #921: a call-shaped PROGRAM document the DATA reading refuses is not
	// a lint parse failure — the dispatch must agree with fmt/run (#391).
	// This exact shape (a call head + a ws-entry map argument) false-failed
	// with the data reader's collection-slot refusal before.
	prog := "[\$xap:component order-card {props: {order: ::string compact: ::bool} view: 'v'}]"
	fs := cx.cx_text_lint(prog, cx.LintOptions{}) or {
		assert false, 'lint refused a program document fmt/run accept: ${err.msg()}'
		return
	}
	assert fs.len == 0, 'no data tree, no doc-shaped findings: ${fs}'
	// A document BOTH readings refuse keeps reporting the data diagnostic.
	if _ := cx.cx_text_lint('{a ::int}', cx.LintOptions{}) {
		assert false, 'both-readings-refused input must still refuse'
	}
}

fn test_l007_fires_on_field_read_aggregation() {
	// the #584 shape verbatim: count over a pure child chain.
	out := l7_out('[?let [= \$b [box [life [evidence [id "e1"]]]]] [\$count \$b/life]]')
	assert l7_count(out) == 1, 'count over a field read must warn: ${out}'
	assert out.contains('§6.2') || out.contains('content'), 'finding must teach the composition: ${out}'
	assert out.contains('//life') || out.contains('predicate'), 'finding must name the sanctioned idioms: ${out}'

	// $empty and $exists share the trap; deeper chains fire too.
	out2 := l7_out('[?let [= \$x [a [b [c 1]]]] [\$empty \$x/a/b]]')
	assert l7_count(out2) == 1, 'empty over a deep field chain must warn: ${out2}'
	out3 := l7_out('[?let [= \$r [res [v [thing]]]] [\$exists \$r/v]]')
	assert l7_count(out3) == 1, 'exists over a field read must warn: ${out3}'

	// nested positions (inside a view literal / for-comp) still fire.
	out4 := l7_out('[?let [= \$b [w [k 1]]] [?for [in \$i (1,2)] [yield [item [\$count \$b/k]]]]]')
	assert l7_count(out4) == 1, 'nested aggregation must warn: ${out4}'
}

fn test_l007_silent_on_sanctioned_forms() {
	// the sanctioned match-counting idioms never fire.
	out := l7_out('[?let [= \$b [box [life [e 1]]]] [\$count \$b//life]]')
	assert l7_count(out) == 0, 'descendant counting must not warn: ${out}'
	out2 := l7_out('[?let [= \$b [box [life [e 1]]]] [\$count \$b/*]]')
	assert l7_count(out2) == 0, 'wildcard counting must not warn: ${out2}'
	out3 := l7_out('[?let [= \$b [box [life [e 1]]]] [\$count \$b/life[= \$_@x 1]]]')
	assert l7_count(out3) == 0, 'predicate step must not warn: ${out3}'

	// bare bindings, dot-chains, and non-aggregation reads are fine.
	out4 := l7_out('[?let [= \$s (1, 2, 3)] [\$count \$s]]')
	assert l7_count(out4) == 0, 'bare-binding count must not warn: ${out4}'
	out5 := l7_out('[?let [= \$m {a: {b: 7}}] [\$count \$m.a]]')
	assert l7_count(out5) == 0, 'map dot-chain must not warn: ${out5}'
	out6 := l7_out('[?let [= \$b [box [life 1]]] \$b/life]')
	assert l7_count(out6) == 0, 'a plain field read must not warn: ${out6}'
}

fn test_l007_suppressable() {
	src := '[?let [= \$b [box [life [e 1]]]] [\$count \$b/life]]'
	out := l7_out(src)
	assert l7_count(out) == 1
	f := os.join_path(os.temp_dir(), 'cx_l007_off_${os.getpid()}.cx')
	os.write_file(f, src) or { panic('write: ${err}') }
	defer { os.rm(f) or {} }
	r := os.execute('${l7_bin()} lint --disable CX-L007 ${f}')
	assert l7_count(r.output) == 0, 'disable flag must suppress: ${r.output}'
}

// ── source: vcx/tests/lint_let_staircase_test.v ──
// lint_let_staircase_test.v — #65: the CX-L006 detect-only lint rule flags a
// PURE nested single-binding [?let] staircase (>= 3 levels) and suggests the
// flat [?let] (let*) form. Detect-only (info severity, no rewrite); non-pure
// nestings and shallow chains are left alone.

fn cx_bin_lint() string {
	return testenv.cx_bin()
}

fn lint_out(src string, extra string) string {
	f := os.join_path(os.temp_dir(), 'cx_l006_${os.getpid()}_${src.len}.cx')
	os.write_file(f, src) or { panic('write: ${err}') }
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin_lint()} lint ${extra} ${f}')
	return r.output
}

fn count_l006(out string) int {
	mut n := 0
	for line in out.split('\n') {
		if line.contains('CX-L006') {
			n++
		}
	}
	return n
}

fn test_three_deep_staircase_flagged() {
	out := lint_out('[?let [= \$a 1] [?let [= \$b 2] [?let [= \$c 3] [+ \$a \$b \$c]]]]', '')
	assert count_l006(out) == 1, 'expected one CX-L006, got: ${out}'
	assert out.contains('3 levels'), 'expected "3 levels", got: ${out}'
}

fn test_flat_let_not_flagged() {
	out := lint_out('[?let [= \$a 1] [= \$b 2] [= \$c 3] [+ \$a \$b \$c]]', '')
	assert count_l006(out) == 0, 'flat let* should not be flagged: ${out}'
}

fn test_two_deep_below_threshold_not_flagged() {
	out := lint_out('[?let [= \$a 1] [?let [= \$b 2] [+ \$a \$b]]]', '')
	assert count_l006(out) == 0, '2-deep is below the threshold, should not flag: ${out}'
}

fn test_non_pure_if_body_not_flagged() {
	// outer [?let] body is an [?if] (lets live in its branches) — not a pure
	// chain, must not be flagged.
	out := lint_out('[?let [= \$a 1] [?if true [then [?let [= \$b 2] [?let [= \$c 3] \$b]]] [else 0]]]',
		'')
	assert count_l006(out) == 0, 'non-pure ([?if]-bodied) let must not flag: ${out}'
}

fn test_multi_binding_breaks_chain() {
	// a middle [?let] with two bindings is not single-binding → no pure
	// 3-chain → no flag.
	out := lint_out('[?let [= \$a 1] [?let [= \$b 2] [= \$b2 3] [?let [= \$c 4] \$a]]]', '')
	assert count_l006(out) == 0, 'multi-binding middle breaks the staircase: ${out}'
}

fn test_four_deep_reports_outermost_once() {
	out := lint_out('[?let [= \$a 1] [?let [= \$b 2] [?let [= \$c 3] [?let [= \$d 4] [+ \$a \$b]]]]]',
		'')
	assert count_l006(out) == 1, 'a 4-deep staircase should flag once (outermost), got: ${out}'
	assert out.contains('4 levels'), 'expected "4 levels", got: ${out}'
}

fn test_disable_suppresses_l006() {
	out := lint_out('[?let [= \$a 1] [?let [= \$b 2] [?let [= \$c 3] \$a]]]', '--disable=CX-L006')
	assert count_l006(out) == 0, '--disable=CX-L006 should suppress it: ${out}'
}

fn test_severity_is_info_not_failing() {
	// info severity must not trip the default --fail-on=error (exit 0).
	f := os.join_path(os.temp_dir(), 'cx_l006_exit_${os.getpid()}.cx')
	os.write_file(f, '[?let [= \$a 1] [?let [= \$b 2] [?let [= \$c 3] \$a]]]') or { panic(err) }
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin_lint()} lint ${f}')
	assert r.exit_code == 0, 'CX-L006 is info severity — must not fail the default gate, got exit ${r.exit_code}: ${r.output}'
	assert r.output.contains('CX-L006'), 'expected the finding in output: ${r.output}'
}

// ── source: vcx/tests/lsp_for_walk_test.v ──
// lsp_for_walk_test.v — stream-2 W2 pins for the L100 ONE-traversal
// contract (`cx.for_comp_children`, vcx/cx/program_for_walk.v) as seen
// through the LSP, plus the #711 item-5 / item-6 surface repairs.
//
// THE DEFECT THESE PIN. Every `[?for]` consumer used to hand-roll the
// clause walk. L100 predicted the walkers would diverge; they had. The
// LSP diagnostic walkers all descended into `clause.source`,
// `clause.expr` and `f.yield` and then STOPPED — none of them ever
// looked at `f.yield_value`, the `[yield-map K V]` VALUE node. So a
// `[?for-map]` whose value expression contained a diagnosable defect
// produced NO diagnostic at all: the editor was silently blind to an
// entire syntactic position.
//
// Measured on the pre-migration binary (stream-2 W2 negative control):
// the CXLS006 infinite-range advisory fired 0 times for a comprehension
// nested in `[yield-map K V]` value position and 1 time after the
// migration. That is the pin below.
//
// The surface pins guard the #711 item-5 repair (the LSP advertised
// colon-slot spellings — `[?let :x 1 :in body]`, `[?for … :return …]` —
// that the PARSER REJECTS, so completion inserted uncompilable syntax)
// and the item-6 / L98 retirement of the `[?for-tumbling]` /
// `[?for-sliding]` head reservations.

fn cx_bin() string {
	return testenv.cx_bin()
}

// frame wraps a JSON-RPC body in an LSP `Content-Length` header.
fn frame(body string) string {
	return 'Content-Length: ${body.len}\r\n\r\n${body}'
}

fn esc_json(s string) string {
	return s.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n').replace('\r',
		'\\r').replace('\t', '\\t')
}

// lsp_session drives `cx lsp` over a full stdin session (initialize →
// didOpen → [extra requests] → shutdown → exit) and returns raw stdout.
fn lsp_session(program string, extra []string) string {
	reqs := frame('{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"capabilities":{}}}') +
		frame('{"jsonrpc":"2.0","method":"initialized","params":{}}') +
		frame('{"jsonrpc":"2.0","method":"textDocument/didOpen","params":{"textDocument":{"uri":"file:///t.cx","languageId":"cx","version":1,"text":"${esc_json(program)}"}}}') +
		extra.map(frame(it)).join('') +
		frame('{"jsonrpc":"2.0","id":99,"method":"shutdown","params":{}}') +
		frame('{"jsonrpc":"2.0","method":"exit","params":{}}')
	reqfile := os.join_path(os.temp_dir(), 'cx_lsp_for_walk_req.txt')
	os.write_file(reqfile, reqs) or { panic('write ${reqfile}: ${err}') }
	return os.execute('${cx_bin()} lsp < ${reqfile}').output
}

// count_code counts occurrences of an LSP diagnostic code in a session.
fn count_code(out string, code string) int {
	needle := '"code":"${code}"'
	mut n := 0
	mut i := 0
	for {
		j := out.index_after(needle, i) or { break }
		n++
		i = j + needle.len
	}
	return n
}

// ── L100 — the ONE traversal reaches [yield-map K V] VALUE position ──

// The CXLS006 infinite-range advisory must fire for an unbounded
// comprehension nested in the `[yield-map K V]` VALUE expression. The
// hand-rolled walk this replaces stopped at `f.yield` and never saw
// that node — 0 diagnostics on the pre-migration binary.
fn test_cxls006_reaches_yield_map_value() {
	prog := '[?for-map [in \$x (1, 2)] [yield-map \$x [?for [in \$y [\$range 1 *]] [yield \$y]]]]'
	out := lsp_session(prog, [])
	assert count_code(out, 'CXLS006') == 1, 'CXLS006 must fire for the unbounded comprehension in [yield-map K V] VALUE position — the walker is blind to f.yield_value:\n${out}'
}

// Control: the SAME unbounded comprehension in KEY position (already
// covered pre-migration) still fires exactly once. Guards against the
// migration double-visiting a node.
fn test_cxls006_in_yield_map_key_fires_once() {
	prog := '[?for-map [in \$x (1, 2)] [yield-map [?for [in \$y [\$range 1 *]] [yield \$y]] \$x]]'
	out := lsp_session(prog, [])
	assert count_code(out, 'CXLS006') == 1, 'CXLS006 must fire exactly once for [yield-map K V] KEY position (no double-visit):\n${out}'
}

// Both positions unbounded → exactly two advisories, one per node.
fn test_cxls006_key_and_value_both_counted() {
	prog := '[?for-map [in \$x (1, 2)] [yield-map [?for [in \$k [\$range 1 *]] [yield \$k]] [?for [in \$v [\$range 1 *]] [yield \$v]]]]'
	out := lsp_session(prog, [])
	assert count_code(out, 'CXLS006') == 2, 'CXLS006 must fire once per unbounded comprehension across BOTH [yield-map K V] slots:\n${out}'
}

// ── #711 item 5 — the completion surface must PARSE ─────────────────

// Every directive completion snippet, stripped of its LSP tab-stops,
// must be accepted by the parser. The retired colon-slot snippets
// (`[?let :name value :in body]`, `[?for x in coll :return body]`)
// failed this: the parser raises CXER0100 on them, so accepting the
// completion produced source that could not compile.
fn test_completion_snippets_parse() {
	out := lsp_session('[doc]', [
		'{"jsonrpc":"2.0","id":2,"method":"textDocument/completion","params":{"textDocument":{"uri":"file:///t.cx"},"position":{"line":0,"character":1}}}',
	])
	// Pull every insertText that looks like a directive snippet.
	mut checked := 0
	mut i := 0
	needle := '"insertText":"'
	for {
		j := out.index_after(needle, i) or { break }
		start := j + needle.len
		// Closing quote of the JSON string — `\"` inside the snippet
		// (the `[?include "path.cx"]` form) is NOT a terminator.
		mut end := start
		for end < out.len && out[end] != `"` {
			end += if out[end] == `\\` { 2 } else { 1 }
		}
		if end >= out.len {
			break
		}
		raw := out[start..end]
		i = end
		if !raw.starts_with('[?') {
			continue
		}
		src := snippet_to_source(raw)
		if src == '' {
			continue
		}
		// PER-DIRECTIVE exemption, each with a stated reason. Deliberately
		// NOT a substring filter on placeholder text: the earlier draft
		// skipped anything containing `path.cx`, and that MASKED the live
		// `?include` surface question entirely.
		//
		// `?include` is a PARSE-time directive in DATA documents (code.md
		// §13, vcx/tests/include_test.v). `cx PROGRAM.cx` drives the CODE
		// path, which refuses it — so it cannot be checked through this
		// CLI harness even though it is a real, spec-approved surface.
		if src.starts_with('[?include') {
			checked++
			continue
		}
		checked++
		f := os.join_path(os.temp_dir(), 'cx_lsp_snip_${checked}.cx')
		os.write_file(f, src) or { panic('write ${f}: ${err}') }
		r := os.execute('${cx_bin()} ${f}')
		assert !r.output.contains('CXER0100'), 'completion snippet does not parse — the LSP is advertising uncompilable syntax (#711 item 5).\n  snippet: ${raw}\n  source:  ${src}\n  output:  ${r.output}'
	}
	assert checked >= 6, 'expected >=6 directive snippets in the completion response, saw ${checked}:\n${out}'
}

// snippet_to_source strips LSP snippet syntax from an insertText: JSON
// unescaping, `${N:placeholder}` → `placeholder`, `$0`/`$N` → '',
// `\$` → `$` (the escaped CX sigil).
//
// NO prose-placeholder escape hatch: an earlier draft skipped snippets
// containing `path.cx` / `cx-source` as "not parse-checkable", and that
// filter MASKED the live `[?include "path.cx"]` defect (`?include` is
// not a directive head at all — inclusion is `[?cx include "path.cx"]`).
// Every snippet the server offers must parse, placeholders and all; a
// snippet that cannot is a snippet that should not be offered.
fn snippet_to_source(raw string) string {
	mut s := raw.replace('\\\\', '\x01').replace('\\"', '"').replace('\x01', '\\')
	// `${N:placeholder}` → `placeholder`
	for {
		open := s.index('\${') or { break }
		close := s.index_after('}', open) or { break }
		inner := s[open + 2..close]
		colon := inner.index(':') or { -1 }
		repl := if colon >= 0 { inner[colon + 1..] } else { '' }
		s = s[..open] + repl + s[close + 1..]
	}
	// Bare `$0` / `$1` … tab-stops (not the escaped `\$` sigil).
	mut out := ''
	mut k := 0
	for k < s.len {
		if s[k] == `\\` && k + 1 < s.len && s[k + 1] == `$` {
			out += '\$'
			k += 2
			continue
		}
		if s[k] == `$` {
			k++
			for k < s.len && s[k] >= `0` && s[k] <= `9` {
				k++
			}
			continue
		}
		out += s[k].ascii_str()
		k++
	}
	return out
}

// The hover tables must not resurrect the retired colon-slot surface.
fn test_for_hover_shows_clause_children_not_colon_slots() {
	prog := '[?for [in \$x (1, 2)] [yield \$x]]'
	out := lsp_session(prog, [
		'{"jsonrpc":"2.0","id":3,"method":"textDocument/hover","params":{"textDocument":{"uri":"file:///t.cx"},"position":{"line":0,"character":2}}}',
	])
	assert out.contains('[in '), '?for hover must document the clause-child surface `[in \$x SRC]`:\n${out}'
	assert !out.contains(':return'), '?for hover still advertises the retired `:return` colon slot (#711 item 5):\n${out}'
	assert !out.contains('tumbling'), '?for hover still advertises windows — retired by L98 (#711 item 6):\n${out}'
	assert !out.contains('on-error'), '?for hover still advertises the retired `[on-error]` clause — the parser refuses it with the §9.3 guidance (#711 items 4/5):\n${out}'
	assert !out.contains('[stream]'), '?for hover still advertises the retired `[stream]` spelling — renamed [lazy] by U1.1a (#763):\n${out}'
	assert out.contains('[lazy]'), '?for hover must document the [lazy] evaluation hint (U1.1a, #763):\n${out}'
}

// ── #711 item 6 / L98 + #760 / RULED 760-1a — retired head reservations ──

// A head whose `[59a]` reservation has been RETIRED must be refused exactly
// the way any unreserved `[?name …]` head is. That is the whole safety
// argument for retiring one: the reservation bought no loudness, because a
// reserved-but-undispatched head and an unknown head raise the identical
// CXER0100. What must NOT happen is a silent downgrade to a processing
// instruction, which would turn a refused program into quiet data.
//
//   L98  — `for-tumbling` / `for-sliding`, the A13/A14 FLWOR window heads.
//   760-1a — `with` / `use` / `cond` / `try`, which parsed as EvalDirectives
//            and were then refused by the §4.1 registry. `try` is
//            additionally a deliberately-retired surface (`make
//            check-no-legacy-try`).
//
// `include` and `def` are deliberately NOT here: both dispatch.
fn test_retired_head_reservations_refused_like_any_unknown_directive() {
	baseline := run_src('[?nosuchdirective a b]')
	assert baseline.contains('CXER0100'), 'expected an unknown-directive CXER0100 baseline, got: ${baseline}'
	for head in ['for-tumbling', 'for-sliding'] {
		out := run_src('[?${head} w [in \$x (1, 2)] [yield \$x]]')
		assert out.contains('CXER0100'), '[?${head}] must be refused LOUDLY after the L98 reservation retirement (never fall through to a PI): ${out}'
		assert out.contains('unknown directive'), '[?${head}] must be refused with the unknown-directive message, matching every other unreserved head: ${out}'
	}
	for head in ['with', 'use', 'cond', 'try'] {
		out := run_src('[?${head} a b]')
		assert out.contains('CXER0100'), '[?${head}] must be refused LOUDLY after the 760-1a reservation retirement (never fall through to a PI): ${out}'
		assert out.contains('unknown directive'), '[?${head}] must be refused with the unknown-directive message, matching every other unreserved head: ${out}'
	}
}

fn run_src(src string) string {
	f := os.join_path(os.temp_dir(), 'cx_l98_probe.cx')
	os.write_file(f, src) or { panic('write ${f}: ${err}') }
	return os.execute('${cx_bin()} ${f}').output
}

// ── source: vcx/tests/lsp_parser_parity_test.v ──
// LSP diagnostic / parser parity.
//
// One cxparse ENGINE, two reading MODES. A `.cx` resource is well-formed if it
// parses under EITHER:
//   • the DATA reading   (cx.parse)         — scannerless; prose, `[- … ]`
//     comments, mixed-content markup (a tour / doc);
//   • the PROGRAM reading (cx.parse_program) — tokenised; `[$call]`, directives,
//     operator heads, program map literals.
// These are modes of the SAME engine, NOT two separate parsers. The LSP
// (vcx/cmd/lsp.v `publish_diagnostics`) therefore raises a syntax diagnostic
// only when BOTH readings fail — exactly the rule this test pins.
//
// Regression history:
//   • Operator heads `[> a b]` / program maps `{k: v k: v}` were flagged as
//     false errors when nvim ran a stale pre-unification binary (its program
//     parser rejected them). Fixed by pointing the editor at the trunk build.
//   • Collapsing the LSP to program-ONLY then wrongly flagged valid DATA
//     documents — a `;` or em-dash in prose / a `[- … ]` comment is fine under
//     the data reading but is not a program token. Hence: accept-under-EITHER.

// Valid under the PROGRAM reading (data reading may reject — that's fine).
const valid_programs = [
	'[> 1 0]',
	'[?if [> [$count 3] 0] [then "yes"] [else "no"]]',
	'{a: 1, b: 2}',
	'{a: 1 b: 2}',
	'{observe: "errors" intents: ([do :add-stock [sym "AAPL"]])}',
	'[?for [in $g $s//group] [where [= $g@name "n"]] [yield $g]]',
	'[?lib \'./x.cx\' as=wl]',
	'[card total=[$count $items]]',
]

// Valid under the DATA reading (program reading rejects the prose/markup —
// `;`, em-dash bytes, mixed content — and that MUST NOT produce a diagnostic).
const valid_data_docs = [
	'[- a block comment with ; and , punctuation ]',
	'[doc [li bare prose with a ; semicolon]]',
	'[doc [p plain mixed content [strong bold] tail]]',
	'[server host=localhost [port::u16 8080]]',
	'[tags::string[] admin user]',
	'[- top comment ]\n[a 1]',
]

// Fails under BOTH readings → a genuine syntax error the LSP SHOULD flag.
const broken_both = [
	'[?if [> 1 0]',   // unterminated
	'[a 1',           // unterminated element
	'{a: 1,,b: 2}',   // empty map slot (rejected by program reading; data too)
]

fn parses_either(src string) bool {
	if _ := cx.parse(src) { return true }
	if _ := cx.parse_program(src) { return true }
	return false
}

fn test_valid_programs_accepted() {
	for src in valid_programs {
		assert parses_either(src), 'LSP would FALSE-flag a valid program: |${src}|'
		// specifically the program reading accepts it
		if _ := cx.parse_program(src) {} else {
			assert false, 'program reading rejected a valid program: |${src}|'
		}
	}
}

fn test_valid_data_docs_accepted() {
	for src in valid_data_docs {
		assert parses_either(src), 'LSP would FALSE-flag a valid data document: |${src}|'
		// specifically the data reading accepts it
		if _ := cx.parse(src) {} else {
			assert false, 'data reading rejected a valid data document: |${src}|'
		}
	}
}

fn test_broken_flagged() {
	for src in broken_both {
		assert !parses_either(src), 'expected BOTH readings to reject (LSP should flag): |${src}|'
	}
}

// ── source: vcx/tests/lsp_semantic_comment_test.v ──

// lsp_semantic_comment_test.v — regression guard for `[; … ]` block-comment
// dimming (cx-private). The LSP semantic-token tokenizer must emit COMMENT
// tokens for the whole `[; … ]` span, not descend into it and emit code tokens
// (atoms / types / directives / bindings). Those code tokens override the
// editor's tmLanguage (VS Code) and tree-sitter (Neovim) comment highlighting —
// which are themselves correct — so the comment interior showed UN-dimmed (the
// repeatedly-reported bug). This drives the real `cx lsp` over JSON-RPC and
// asserts the semantic-token TYPE ids.
//
// tt_comment is index 7 in the semanticTokens legend (vcx/cmd/lsp_content.v).
const tt_comment = 7

fn json_escape(s string) string {
	return s.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n').replace('\r',
		'\\r').replace('\t', '\\t')
}

// semantic_token_types drives `cx lsp` on `program` and returns the flat list of
// semantic-token TYPE ids (one per token). A full session is piped on stdin
// (initialize → didOpen → semanticTokens/full → shutdown → exit) so the server
// terminates and os.execute returns.
fn semantic_token_types(program string) []int {
	esc := json_escape(program)
	reqs := frame('{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"capabilities":{}}}') +
		frame('{"jsonrpc":"2.0","method":"initialized","params":{}}') +
		frame('{"jsonrpc":"2.0","method":"textDocument/didOpen","params":{"textDocument":{"uri":"file:///t.cx","languageId":"cx","version":1,"text":"${esc}"}}}') +
		frame('{"jsonrpc":"2.0","id":2,"method":"textDocument/semanticTokens/full","params":{"textDocument":{"uri":"file:///t.cx"}}}') +
		frame('{"jsonrpc":"2.0","id":3,"method":"shutdown","params":{}}') +
		frame('{"jsonrpc":"2.0","method":"exit","params":{}}')
	reqfile := os.join_path(os.temp_dir(), 'cx_lsp_sem_req.txt')
	os.write_file(reqfile, reqs) or { panic('write ${reqfile}: ${err}') }
	r := os.execute('${cx_bin()} lsp < ${reqfile}')
	out := r.output
	// Only the semanticTokens response carries a "data" array.
	marker := '"data":['
	idx := out.index(marker) or { panic('no semanticTokens data in LSP output:\n${out}') }
	rest := out[idx + marker.len..]
	endi := rest.index(']') or { panic('unterminated data array in:\n${out}') }
	mut data := []int{}
	for n in rest[..endi].split(',') {
		t := n.trim_space()
		if t != '' {
			data << t.int()
		}
	}
	// Each token is 5 ints: [deltaLine, deltaStart, length, TYPE, modifiers].
	mut types := []int{}
	mut k := 3
	for k < data.len {
		types << data[k]
		k += 5
	}
	return types
}

// A `[; … ]` comment — multi-line, with a nested bracket, an atom, a binding,
// and a directive head — each of which WOULD get a code token if the tokenizer
// descended into the comment. The whole span must be comment.
fn test_block_comment_interior_is_all_comment() {
	prog := '[; header [tbl col:int]\n   :atom \$bind and ?key here ]'
	types := semantic_token_types(prog)
	assert types.len > 0, 'expected >=1 semantic token for the [; … ] comment (got none)'
	for t in types {
		assert t == tt_comment, 'a token inside [; … ] is type ${t}, not comment (${tt_comment}) — interior leaked as code: ${types}'
	}
}

// Guard against over-dimming: real code around a `[; … ]` comment must keep its
// (non-comment) tokens; only the comment dims.
fn test_code_around_block_comment_keeps_code_tokens() {
	prog := '[greet name=x]\n[; just :atom \$b ]\n[other]'
	types := semantic_token_types(prog)
	assert tt_comment in types, 'expected the [; … ] line to emit a comment token: ${types}'
	mut has_code := false
	for t in types {
		if t != tt_comment {
			has_code = true
		}
	}
	assert has_code, 'expected code tokens for the [greet]/[other] lines — over-dimmed: ${types}'
}

// ── CX-L008 — declared [?pipe] stage flow (I5-s16 W5, Layer B at the ──
// lint dial): warn default, --fail-on escalation; the runtime refusal
// is --strict's job.

const l8_bad = "[?def to-text [returns string] (\$x::int) 'n']\n[?def shout [returns string] (\$s::string) \$s]\n[?pipe 3 to-text shout to-text]\n"
const l8_ok = "[?def to-text [returns string] (\$x::int) 'n']\n[?def double [returns int] (\$x::int) [* \$x 2]]\n[?pipe 3 double to-text]\n"

fn l8_run(src string, flags string) (string, int) {
	f := os.join_path(os.temp_dir(), 'cx_l008_${os.getpid()}_${src.len}.cx')
	os.write_file(f, src) or { panic('write: ${err}') }
	defer { os.rm(f) or {} }
	r := os.execute('${l7_bin()} lint ${flags} ${f}')
	return r.output, r.exit_code
}

fn test_l008_fires_on_declared_stage_mismatch() {
	out, rc := l8_run(l8_bad, '')
	assert out.contains('CX-L008'), out
	assert out.contains('shout') && out.contains('to-text'), 'must name both stages: ${out}'
	assert rc == 0, 'warn severity — default run exits 0'
}

fn test_l008_fail_on_warn_escalates() {
	_, rc := l8_run(l8_bad, '--fail-on=warn')
	assert rc == 1
}

fn test_l008_silent_on_composing_and_undeclared_boundaries() {
	out, _ := l8_run(l8_ok, '')
	assert !out.contains('CX-L008'), out
	// An undeclared boundary (no [returns]) is silent — declarations
	// are the contract, absence is not a finding.
	out2, _ := l8_run("[?def f (\$x) \$x]\n[?def g [returns int] (\$s::string) 1]\n[?pipe 3 f g]\n", '')
	assert !out2.contains('CX-L008'), out2
}

fn test_l008_disable_honored() {
	out, _ := l8_run(l8_bad, '--disable CX-L008')
	assert !out.contains('CX-L008'), out
}

// ── #705 — the LSP directive surface is the REGISTRY, exactly ─────────
//
// POST-APPLY umbrella addition — not in
// scripts/consolidation/lint_lsp.files; reconcile it into the manifest
// inputs before any future regeneration.
//
// The hand-kept completion list had drifted into a different language:
// four advertised heads did not exist at either layer (`?xpath`,
// `?xquery`, `?cxpath` were pure LSP invention; `?include` is a
// DATA-document assembly directive, not an eval-time head), and the
// snippets documented an abolished slot syntax. governance.md §10.2
// requires an LSP update on every grammar change — nothing enforced it.
//
// The set is now DERIVED from cx.directive_names, and this gate proves it
// over the SHIPPED binary rather than the source: a completion response
// is parsed and its directive labels compared to the registry in both
// directions. Advertising a head no parser knows is the same defect class
// the shell-completion drift gate exists to prevent.
fn test_lsp_directive_surface_equals_the_registry() {
	out := lsp_session('[doc]', [
		'{"jsonrpc":"2.0","id":2,"method":"textDocument/completion","params":{"textDocument":{"uri":"file:///t.cx"},"position":{"line":0,"character":1}}}',
	])
	mut offered := map[string]bool{}
	needle := '"label":"'
	mut i := 0
	for {
		j := out.index_after(needle, i) or { break }
		start := j + needle.len
		mut end := start
		for end < out.len && out[end] != `"` {
			end += if out[end] == `\\` { 2 } else { 1 }
		}
		if end >= out.len {
			break
		}
		label := out[start..end]
		i = end
		if label.starts_with('?') {
			offered[label] = true
		}
	}
	assert offered.len > 0, 'the completion response advertised no directives — the gate has nothing to enforce'

	mut registry := map[string]bool{}
	for n in cx.directive_names {
		registry['?' + n] = true
	}

	mut phantom := []string{}
	for label, _ in offered {
		if label !in registry {
			phantom << label
		}
	}
	assert phantom.len == 0, 'the LSP advertises directives that are NOT in cx.directive_names — ' +
		'a head no parser knows (#705): ${phantom.join(', ')}'

	mut missing := []string{}
	for name, _ in registry {
		if name !in offered {
			missing << name
		}
	}
	assert missing.len == 0, 'these registry directives are missing from the LSP completion set — ' +
		'the surface lags the grammar, which governance.md §10.2 forbids (#705): ${missing.join(', ')}'
}
